use std::io

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct RTri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for RTri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(s: string) -> int {
    s.parse::<int>() ?? 0
}

fn parse(line: string) -> Option<Box<dyn Shape>> {
    let p: Vec<string> = line.split_whitespace().collect()
    if p.len() == 0 {
        return None
    }
    let k = p[0]
    if k == "square" && p.len() >= 2 {
        return Some(Box::new(Square { s: num(p[1]) }))
    }
    if k == "rect" && p.len() >= 3 {
        return Some(Box::new(Rect { w: num(p[1]), h: num(p[2]) }))
    }
    if k == "rtri" && p.len() >= 3 {
        return Some(Box::new(RTri { a: num(p[1]), b: num(p[2]) }))
    }
    if k == "trap" && p.len() >= 4 {
        return Some(Box::new(Trap { a: num(p[1]), b: num(p[2]), h: num(p[3]) }))
    }
    None
}

fn main() {
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    loop {
        let r = io.read_line()
        match r {
            Ok(l) => {
                if l.len() == 0 { break }
                match parse(l) {
                    Some(s) => {
                        let d = s.double_area()
                        println("${s.name()} corners=${s.corners()} area2=${d}")
                        total += d
                        if d > best {
                            best = d
                            best_name = s.name()
                        }
                    }
                    None => {}
                }
            }
            Err(_) => { break }
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

